// Validación y Enriquecimiento
// Ahora el payload ya viene limpio del ESP32
const device = items[0].json;
const gateway_info = items[0].binary ? {} : {}; // Contexto si fuera necesario

// Estimación de distancia con RSSI promedio
const txPower = -59;
const n = 2;
// Usamos 'avg_rssi' calculado en el borde
const distance = Math.pow(10, (txPower - device.avg_rssi) / (10 * n));

return {
  json: {
    mac: device.mac,
    name: device.name || 'Unknown',
    rssi: device.avg_rssi,
    samples: device.count,
    distance_m: parseFloat(distance.toFixed(2)),
    status: device.avg_rssi > -70 ? 'Cerca' : 'Lejos',
    processed_at: new Date().toISOString()
  }
};
